#!/usr/bin/env python3# ts_layer4_metacheck.py | TS-Validator Layer 4 (MetaCheck v1.4)import json, osdef run_metacheck():    report_path = "ts_sandbox_report.json"    if not os.path.exists(report_path):        print("❌ Отчёт sandbox не найден. Сначала запустите ts_d_sandbox.py")        return False    with open(report_path) as f:        report = json.load(f)    print("🔍 Запуск TS-Validator Layer 4: MetaCheck...")    epsilon_X = 0.25    avg_friction = report["avg_friction_on_pass"]    delta_gamma_X = max(0.0, 1.0 - avg_friction)    # ✅ FIX: Численная точность (tolerance 1e-4) + динамический порог    tolerance = 1e-4    optimizer_approved = avg_friction <= (report["epsilon_friction_recommended"] + tolerance)    valid_ratio = report["valid_bindings"] / report["total_cycles"]    c_validated = valid_ratio > 0.60    meta_pass = (delta_gamma_X > epsilon_X) and optimizer_approved and c_validated    print(f"   ΔΓ_X: {round(delta_gamma_X, 4)} > ε_X ({epsilon_X}) ? {'✅' if delta_gamma_X > epsilon_X else '❌'}")    print(f"   TS-Optimizer (friction ≤ {report['epsilon_friction_recommended']} ± {tolerance}): {'✅' if optimizer_approved else '❌'}")    print(f"   C-invariants (valid_bindings > 60% | {valid_ratio*100:.1f}%): {'✅' if c_validated else '❌'}")    if meta_pass:        print("\n🎉 LAYER 4: PASS → X_Commit_Lock открыт. Допустим конституционный апгрейд.")    else:        print("\n⚠️  LAYER 4: PENDING → Требуется дополнительная калибровка.")    return meta_passif __name__ == "__main__":    run_metacheck()